<section class="panel"><h2>Сигналы и сроки</h2><?php if($incidentManage&&$policy&&(int)$policy['active']): ?><form method="post" class="inline"><?php formFields('incident.scan') ?><input type="hidden" name="project_id" value="<?= (int)$p ?>"><button class="primary">Собрать актуальные сигналы (MFA)</button></form><p>Перед сбором выполните <a href="<?= h(url('infrastructure',['project'=>$p])) ?>">сверку инфраструктуры</a>. Logs: последние 24 часа, до 50 событий на уровень.</p><?php endif ?>
<?php if($incidentRelease!==null): ?><p>Выпуск #<?= (int)$incidentRelease ?> · <a href="<?= h(url('incidents',['project'=>$p])) ?>">Все инциденты</a></p><?php endif ?>
<div class="tablewrap"><table><thead><tr><th>Инцидент</th><th>Окружение / выпуск</th><th>Ответственный</th><th>Состояние</th><th>Срок реакции</th></tr></thead><tbody><?php foreach($incidentRows as $i): $late=($i['acknowledged_at']===null?time():(int)$i['acknowledged_at'])>(int)$i['response_due']; ?><tr><td><a href="<?= h(url('incidents',['project'=>$p,'id'=>$i['id']])) ?>">#<?= (int)$i['id'] ?> <?= h(INCIDENT_CONDITIONS[$i['condition_code']]??$i['condition_code']) ?></a> · <?= h($i['severity']) ?></td><td><?= h($i['environment']??'—') ?> / <?= h($i['release_id']??'—') ?></td><td><?= h($i['responsible_name']) ?></td><td><?= h($i['state']) ?></td><td><?= h($dt($i['response_due'])) ?><?= $late?' · ПРОСРОЧЕНО':'' ?></td></tr><?php endforeach ?></tbody></table></div><p>До 100 карточек, открытые первыми.</p></section>
<?php if($r): $id=(int)$r['id'];$assigned=(int)$r['responsible_id']===(int)$user['id']; ?>
<section class="panel"><h2>#<?= $id ?> · <?= h(INCIDENT_CONDITIONS[$r['condition_code']]??$r['condition_code']) ?></h2><p>Источник: <?= h($r['source']) ?> · объект #<?= (int)$r['object_id'] ?> · <?= h($r['environment']??'—') ?> · <?= h($r['state']) ?></p><p>Ответственный #<?= (int)$r['responsible_id'] ?><?= $incidentManage&&!isset($incidentPeople[$r['responsible_id']])?' (доступ отозван, назначьте нового)':'' ?> · срок <?= h($dt($r['response_due'])) ?> · реакция <?= h($dt($r['acknowledged_at'])) ?> · закрытие <?= h($dt($r['resolved_at'])) ?></p><p>Проверенное восстановление <?= h($dt($r['verification_at'])) ?> · метод <?= h($r['verification_mode']??'—') ?></p><p>Первый сигнал <?= h($dt($r['first_signal_at'])) ?> · последний <?= h($dt($r['last_signal_at'])) ?></p><?php if($r['release_id']!==null): ?><p><a href="<?= h(url('releases',['project'=>$p,'id'=>$r['release_id']])) ?>">Выпуск #<?= (int)$r['release_id'] ?></a> · <a href="<?= h(url('logs',['project'=>$p,'release'=>$r['release_id']])) ?>">Logs выпуска</a> · <a href="<?= h(url('release_trace',['project'=>$p,'id'=>$r['release_id']]+(!empty($incidentTraceJob)?['job'=>$incidentTraceJob]:[]))) ?>">След выпуска и эксплуатации</a></p><?php endif ?>
