<section class="panel"><h2>История и отчёт (последние 100)</h2><?php foreach($incidentEvents as $e): ?><p><?= h($dt($e['created_at'])) ?> · <?= h($e['event']) ?> · пользователь #<?= (int)$e['actor_id'] ?></p><pre class="release-text"><?= h($e['detail']) ?></pre><?php endforeach ?></section>
